130	function getStackedOnPoints(
131	    coordSys: Cartesian2D | Polar,
132	    data: SeriesData,
133	    dataCoordInfo: ReturnType<typeof prepareDataCoordInfo>
134	) {
135	    if (!dataCoordInfo.valueDim) {
136	        return [];
137	    }
138	
139	    const len = data.count();
140	    const points = createFloat32Array(len * 2);
141	    for (let idx = 0; idx < len; idx++) {
142	        const pt = getStackedOnPoint(dataCoordInfo, coordSys, data, idx);
143	        points[idx * 2] = pt[0];
144	        points[idx * 2 + 1] = pt[1];
145	    }
146	
147	    return points;
148	}
