150	/**
151	 * Filter the null data and extend data for step considering `stepTurnAt`
152	 *
153	 * @param points data to convert, that may containing null
154	 * @param basePoints base data to reference, used only for areaStyle points
155	 * @param coordSys coordinate system
156	 * @param stepTurnAt 'start' | 'end' | 'middle' | true
157	 * @param connectNulls whether to connect nulls
158	 * @returns converted point positions
159	 */
160	function turnPointsIntoStep(
161	    points: ArrayLike<number>,
162	    basePoints: ArrayLike<number> | null,
163	    coordSys: Cartesian2D | Polar,
164	    stepTurnAt: 'start' | 'end' | 'middle',
165	    connectNulls: boolean
166	): number[] {
167	    const baseAxis = coordSys.getBaseAxis();
168	    const baseIndex = baseAxis.dim === 'x' || baseAxis.dim === 'radius' ? 0 : 1;
169	
170	    const stepPoints: number[] = [];
171	    let i = 0;
172	    const stepPt: number[] = [];
173	    const pt: number[] = [];
174	    const nextPt: number[] = [];
175	    const filteredPoints = [];
176	    if (connectNulls) {
177	        for (i = 0; i < points.length; i += 2) {
178	            /**
179	             * For areaStyle of stepped lines, `stackedOnPoints` should be
180	             * filtered the same as `points` so that the base axis values
181	             * should stay the same as the lines above. See #20021
182	             */
183	            const reference = basePoints || points;
184	            if (!isNaN(reference[i]) && !isNaN(reference[i + 1])) {
185	                filteredPoints.push(points[i], points[i + 1]);
186	            }
187	        }
188	        points = filteredPoints;
189	    }
190	    for (i = 0; i < points.length - 2; i += 2) {
191	        nextPt[0] = points[i + 2];
192	        nextPt[1] = points[i + 3];
193	        pt[0] = points[i];
194	        pt[1] = points[i + 1];
195	        stepPoints.push(pt[0], pt[1]);
196	
197	        switch (stepTurnAt) {
198	            case 'end':
199	                stepPt[baseIndex] = nextPt[baseIndex];
200	                stepPt[1 - baseIndex] = pt[1 - baseIndex];
201	                stepPoints.push(stepPt[0], stepPt[1]);
202	                break;
203	            case 'middle':
204	                const middle = (pt[baseIndex] + nextPt[baseIndex]) / 2;
205	                const stepPt2 = [];
206	                stepPt[baseIndex] = stepPt2[baseIndex] = middle;
207	                stepPt[1 - baseIndex] = pt[1 - baseIndex];
208	                stepPt2[1 - baseIndex] = nextPt[1 - baseIndex];
209	                stepPoints.push(stepPt[0], stepPt[1]);
210	                stepPoints.push(stepPt2[0], stepPt2[1]);
211	                break;
212	            default:
213	                // default is start
214	                stepPt[baseIndex] = pt[baseIndex];
215	                stepPt[1 - baseIndex] = nextPt[1 - baseIndex];
216	                stepPoints.push(stepPt[0], stepPt[1]);
217	        }
218	    }
219	    // Last points

