21	import SeriesDimensionDefine from '../SeriesDimensionDefine';
22	import SeriesModel from '../../model/Series';
23	import SeriesData, { DataCalculationInfo } from '../SeriesData';
24	import type { SeriesOption, SeriesStackOptionMixin, DimensionName } from '../../util/types';
25	import { isSeriesDataSchema, SeriesDataSchema } from './SeriesDataSchema';
26	import DataStore from '../DataStore';
27	
28	type EnableDataStackDimensionsInput = {
29	    schema: SeriesDataSchema;
30	    // If given, stack dimension will be ensured on this store.
31	    // Otherwise, stack dimension will be appended at the tail, and should not
32	    // be used on a shared store, but should create a brand new storage later.
33	    store?: DataStore;
34	};
35	type EnableDataStackDimensionsInputLegacy = (SeriesDimensionDefine | string)[];
36	
37	/**
38	 * Note that it is too complicated to support 3d stack by value
39	 * (have to create two-dimension inverted index), so in 3d case
40	 * we just support that stacked by index.
41	 *
42	 * @param seriesModel
43	 * @param dimensionsInput The same as the input of <module:echarts/data/SeriesData>.
44	 *        The input will be modified.
45	 * @param opt
46	 * @param opt.stackedCoordDimension Specify a coord dimension if needed.
47	 * @param opt.byIndex=false
48	 * @return calculationInfo
49	 * {
50	 *     stackedDimension: string
51	 *     stackedByDimension: string
52	 *     isStackedByIndex: boolean
53	 *     stackedOverDimension: string
54	 *     stackResultDimension: string
55	 * }
56	 */
57	export function enableDataStack(
58	    seriesModel: SeriesModel<SeriesOption & SeriesStackOptionMixin>,
59	    dimensionsInput: EnableDataStackDimensionsInput | EnableDataStackDimensionsInputLegacy,
60	    opt?: {
61	        // Backward compat
62	        stackedCoordDimension?: string
63	        byIndex?: boolean
64	    }
65	): Pick<
66	    DataCalculationInfo<unknown>,
67	    'stackedDimension'
68	    | 'stackedByDimension'
69	    | 'isStackedByIndex'
70	    | 'stackedOverDimension'
71	    | 'stackResultDimension'
72	> {
73	    opt = opt || {};
74	    let byIndex = opt.byIndex;
75	    const stackedCoordDimension = opt.stackedCoordDimension;
76	
77	    let dimensionDefineList: EnableDataStackDimensionsInputLegacy;
78	    let schema: SeriesDataSchema;
79	    let store: DataStore;
80	
81	    if (isLegacyDimensionsInput(dimensionsInput)) {
82	        dimensionDefineList = dimensionsInput;
83	    }
84	    else {
85	        schema = dimensionsInput.schema;
86	        dimensionDefineList = schema.dimensions;
87	        store = dimensionsInput.store;
88	    }
89	
90	    // Compatibal: when `stack` is set as '', do not stack.
91	    const mayStack = !!(seriesModel && seriesModel.get('stack'));
92	    let stackedByDimInfo: SeriesDimensionDefine;
93	    let stackedDimInfo: SeriesDimensionDefine;
94	    let stackResultDimension: string;
95	    let stackedOverDimension: string;
96	
97	    each(dimensionDefineList, function (dimensionInfo, index) {
98	        if (isString(dimensionInfo)) {
99	            dimensionDefineList[index] = dimensionInfo = {
100	                name: dimensionInfo as string
101	            } as SeriesDimensionDefine;
102	        }
103	
104	        if (mayStack && !dimensionInfo.isExtraCoord) {
105	            // Find the first ordinal dimension as the stackedByDimInfo.
106	            if (!byIndex && !stackedByDimInfo && dimensionInfo.ordinalMeta) {
107	                stackedByDimInfo = dimensionInfo;
108	            }
109	            // Find the first stackable dimension as the stackedDimInfo.
110	            if (!stackedDimInfo
111	                && dimensionInfo.type !== 'ordinal'
112	                && dimensionInfo.type !== 'time'
113	                && (!stackedCoordDimension || stackedCoordDimension === dimensionInfo.coordDim)
114	            ) {
115	                stackedDimInfo = dimensionInfo;
116	            }
117	        }
118	    });
119	
120	    if (stackedDimInfo && !byIndex && !stackedByDimInfo) {
121	        // Compatible with previous design, value axis (time axis) only stack by index.
122	        // It may make sense if the user provides elaborately constructed data.
123	        byIndex = true;
124	    }
125	
126	    // Add stack dimension, they can be both calculated by coordinate system in `unionExtent`.
127	    // That put stack logic in List is for using conveniently in echarts extensions, but it
128	    // might not be a good way.
129	    if (stackedDimInfo) {
130	        // Use a weird name that not duplicated with other names.
131	        // Also need to use seriesModel.id as postfix because different
132	        // series may share same data store. The stack dimension needs to be distinguished.
133	        stackResultDimension = '__\0ecstackresult_' + seriesModel.id;
134	        stackedOverDimension = '__\0ecstackedover_' + seriesModel.id;
135	
136	        // Create inverted index to fast query index by value.
137	        if (stackedByDimInfo) {
138	            stackedByDimInfo.createInvertedIndices = true;
139	        }
140	
141	        const stackedDimCoordDim = stackedDimInfo.coordDim;
142	        const stackedDimType = stackedDimInfo.type;
143	        let stackedDimCoordIndex = 0;
144	
145	        each(dimensionDefineList, function (dimensionInfo: SeriesDimensionDefine) {
146	            if (dimensionInfo.coordDim === stackedDimCoordDim) {
147	                stackedDimCoordIndex++;
148	            }
149	        });
150	
151	        const stackedOverDimensionDefine: SeriesDimensionDefine = {
152	            name: stackResultDimension,
153	            coordDim: stackedDimCoordDim,
154	            coordDimIndex: stackedDimCoordIndex,
155	            type: stackedDimType,
156	            isExtraCoord: true,
157	            isCalculationCoord: true,
158	            storeDimIndex: dimensionDefineList.length
159	        };
160	
161	        const stackResultDimensionDefine: SeriesDimensionDefine = {
162	            name: stackedOverDimension,
163	            // This dimension contains stack base (generally, 0), so do not set it as
164	            // `stackedDimCoordDim` to avoid extent calculation, consider log scale.
165	            coordDim: stackedOverDimension,
166	            coordDimIndex: stackedDimCoordIndex + 1,
167	            type: stackedDimType,
168	            isExtraCoord: true,
169	            isCalculationCoord: true,
170	            storeDimIndex: dimensionDefineList.length + 1
171	        };
172	
173	        if (schema) {
174	            if (store) {
175	                stackedOverDimensionDefine.storeDimIndex =
176	                    store.ensureCalculationDimension(stackedOverDimension, stackedDimType);
177	                stackResultDimensionDefine.storeDimIndex =
178	                    store.ensureCalculationDimension(stackResultDimension, stackedDimType);
179	            }
180	
181	            schema.appendCalculationDimension(stackedOverDimensionDefine);
182	            schema.appendCalculationDimension(stackResultDimensionDefine);
183	        }
184	        else {
185	            dimensionDefineList.push(stackedOverDimensionDefine);
186	            dimensionDefineList.push(stackResultDimensionDefine);
187	        }
188	    }
189	
190	    return {
191	        stackedDimension: stackedDimInfo && stackedDimInfo.name,
192	        stackedByDimension: stackedByDimInfo && stackedByDimInfo.name,
193	        isStackedByIndex: byIndex,
194	        stackedOverDimension: stackedOverDimension,
195	        stackResultDimension: stackResultDimension
196	    };
197	}
198	
199	function isLegacyDimensionsInput(
200	    dimensionsInput: Parameters<typeof enableDataStack>[1]
201	): dimensionsInput is EnableDataStackDimensionsInputLegacy {
202	    return !isSeriesDataSchema((dimensionsInput as EnableDataStackDimensionsInput).schema);
203	}
204	
205	export function isDimensionStacked(data: SeriesData, stackedDim: string): boolean {
206	    // Each single series only maps to one pair of axis. So we do not need to
207	    // check stackByDim, whatever stacked by a dimension or stacked by index.
208	    return !!stackedDim && stackedDim === data.getCalculationInfo('stackedDimension');
209	}
210	
211	export function getStackedDimension(data: SeriesData, targetDim: string): DimensionName {
212	    return isDimensionStacked(data, targetDim)
213	        ? data.getCalculationInfo('stackResultDimension')
214	        : targetDim;
215	}
